DO $$
DECLARE
  v_cid UUID;
  v_ch  UUID;
BEGIN
  SELECT id INTO v_cid FROM public.courses
    WHERE curriculum_version = 'cyber-v1';
  IF v_cid IS NULL THEN RAISE EXCEPTION 'Cyber course not found'; END IF;

-- ─── MODULE 13: Identity Security & Privileged Access Management ──────────────

  SELECT id INTO v_ch FROM public.chapters
    WHERE course_id = v_cid ORDER BY order_index LIMIT 1 OFFSET 12;
  IF v_ch IS NULL THEN RAISE EXCEPTION 'M13 chapter not found'; END IF;

  UPDATE public.videos SET
    description = 'Identity is the new perimeter in Zero Trust architecture. Learn identity pillars, ITDR, and why compromised credentials are the root cause of 80% of enterprise breaches.',
    translations = jsonb_build_object('en', jsonb_build_object(
      'title', 'Zero Trust Identity Architecture — Identity as the New Perimeter',
      'description', 'Identity is the new perimeter in Zero Trust architecture. Learn identity pillars, ITDR, and why compromised credentials are the root cause of 80% of enterprise breaches.',
      'transcript', 'The shift to Zero Trust architecture has elevated identity to the primary security boundary of the enterprise. In the old perimeter model, trust was granted based on network location — if you were inside the corporate network, you were trusted. In Zero Trust, network location is irrelevant. Every access request must be explicitly authenticated and authorized, regardless of where it originates. The entity making the request — the identity — is the only thing that can establish trust.

Compromised credentials are the root cause of approximately 80% of enterprise breaches. Attackers obtain credentials through phishing, credential stuffing attacks against reused passwords, purchasing credentials from dark web breach databases, or extracting credentials from compromised systems using tools like Mimikatz. Once an attacker has valid credentials, they can authenticate as the legitimate user to cloud consoles, SaaS applications, VPNs, and internal systems — bypassing network-layer controls entirely. Traditional perimeter security cannot defend against this because the attacker is presenting valid credentials.

Zero Trust identity architecture rests on four pillars. First: Strong Authentication. Every user must authenticate with phishing-resistant MFA. Password + SMS OTP is insufficient — SIM-swapping and real-time phishing proxies (tools like Evilginx) can defeat SMS MFA in real time. FIDO2/WebAuthn hardware keys and passkeys are phishing-resistant because the credential is bound to the specific website — a FIDO2 key cannot be phished because it will not respond to a fake login page. Second: Device Health Verification. Access decisions must factor in the security state of the requesting device. A compromised laptop should not receive the same access as a healthy, managed device with current patches and EDR coverage. Device compliance enforcement via MDM (Intune, Jamf) feeds signals into Conditional Access policies. Third: Least-Privilege Access. Every identity should have only the minimum permissions required. This limits blast radius when credentials are compromised — a compromised account with read-only access to one system is far less damaging than a compromised account with admin rights across the environment. Fourth: Continuous Evaluation. Trust is not granted once at login and maintained indefinitely. Risk signals during an active session — impossible travel, anomalous data access patterns, new device enrollment — should trigger step-up authentication or session termination.

Identity Threat Detection and Response (ITDR) is the emerging discipline of detecting and responding to identity-based attacks. ITDR capabilities: detection of credential stuffing attacks on login endpoints, detection of MFA fatigue attacks (abnormal push notification volume to a user), detection of impossible travel (authenticated from New York, then from Tokyo 20 minutes later — impossible by air), detection of abnormal privilege use (a user account suddenly accessing hundreds of files it has never accessed before), and automated response (disable the account, revoke sessions, trigger MFA re-enrollment). ITDR platforms integrate identity provider logs, EDR telemetry, and network logs to build a complete picture of identity behavior across all authentication points.

Microsoft Entra ID Identity Protection, Okta ThreatInsight, and dedicated ITDR platforms (Silverfort, Authomize) provide ITDR capabilities. The ITDR signal set is particularly valuable for detecting lateral movement — the phase between initial credential compromise and the attacker reaching their objective. Every lateral movement attempt requires additional authentication events, which ITDR systems can correlate into a timeline that traces the entire attack path.'
    ))
  WHERE chapter_id = v_ch AND order_index = 1;

  UPDATE public.videos SET
    description = 'PAM protects the most dangerous accounts in the enterprise. Master CyberArk, BeyondTrust, and Delinea architectures, JIT access models, session recording, and privileged account lifecycle management.',
    translations = jsonb_build_object('en', jsonb_build_object(
      'title', 'Privileged Access Management (PAM) — CyberArk, BeyondTrust & Delinea',
      'description', 'PAM protects the most dangerous accounts in the enterprise. Master CyberArk, BeyondTrust, and Delinea architectures, JIT access, session recording, and privileged account lifecycle management.',
      'transcript', 'Privileged accounts — domain administrators, root accounts, service accounts, database administrators, and break-glass emergency accounts — represent the most dangerous identity class in the enterprise. A compromised privileged account gives an attacker unrestricted access to the systems that account controls. Privileged Access Management (PAM) exists to ensure that even if an attacker compromises a privileged account, the damage they can do is limited by controls that restrict when, how, and for how long that account can be used.

The core PAM problem: privileged credentials are inherently dangerous because they are powerful, and they are traditionally managed poorly. Domain administrator passwords known by multiple team members and shared over Slack. Root credentials stored in plain text in a shared spreadsheet. Service account passwords that have not been rotated in three years because the team is afraid changing them will break the application. Database administrator credentials that are the same across development, staging, and production. PAM eliminates these problems through centralized, automated credential management.

PAM core capabilities: Password Vaulting — privileged credentials are stored in an encrypted vault. Human operators never know the actual password — they request access, authenticate to the vault, and receive a time-limited session. The vault checks out the credential, provides a one-time session token, and rotates the underlying credential after each use. No human ever needs to know the root password. Just-In-Time (JIT) Access — privileges are granted only when needed for a specific task, with a defined expiration. A system administrator needing to restart a service requests domain admin access for two hours, provides a business justification, gets approval from their manager, performs the task, and has their privileges automatically revoked at expiration. Session Recording — every privileged session is recorded in its entirety: keystrokes, commands, files accessed, data exported. Session recordings provide forensic evidence for incident investigations, compliance demonstrations for SOC 2 and ISO 27001 auditors, and behavioral baselines for UEBA anomaly detection. Privileged Session Management — PAM platforms proxy privileged sessions, meaning the privileged account credentials are never exposed to the operator''s workstation. If the operator''s laptop is compromised, the attacker cannot extract the privileged credential from memory.

CyberArk PAM (market leader): enterprise-grade, most comprehensive capabilities, strongest for large organizations with complex privileged access needs. CyberArk Privilege Cloud (SaaS) or self-hosted. CyberArk Conjur for DevOps secrets management (API credentials, CI/CD pipeline secrets). BeyondTrust Password Safe: strong for mixed Windows/Linux environments, excellent reporting, well-integrated with Active Directory. BeyondTrust Remote Support adds session brokering for vendor remote access sessions — critical for third-party risk management (vendors accessing your systems should go through a PAM-brokered session, not direct VPN access). Delinea Secret Server: mid-market positioning, strong user experience, well-suited for organizations scaling from basic password management to full PAM.

Service account governance within PAM: service accounts (accounts used by applications and automated processes, not humans) are the most commonly overlooked privileged access problem. Service accounts accumulate excessive permissions over time, use static passwords that are never rotated, and are rarely deprovisioned when the application they serve is decommissioned. Modern PAM approach: use dynamic secrets (database credentials generated on-demand and expiring automatically — HashiCorp Vault, CyberArk for applications), implement service account discovery (identify all service accounts in Active Directory and cloud environments), and implement regular service account access reviews to remove excessive permissions and decommission unused accounts.'
    ))
  WHERE chapter_id = v_ch AND order_index = 2;

  UPDATE public.videos SET
    description = 'SSO, SAML, OAuth 2.0, OIDC, and SCIM are the federation standards that power modern enterprise identity. Master the flows, the security properties, and the misconfigurations that create exploitable vulnerabilities.',
    translations = jsonb_build_object('en', jsonb_build_object(
      'title', 'SSO, SAML 2.0, OAuth 2.0, OIDC & Federation Standards Deep Dive',
      'description', 'SSO, SAML, OAuth 2.0, OIDC, and SCIM are the federation standards powering modern enterprise identity. Master the flows, security properties, and exploitable misconfigurations.',
      'transcript', 'Modern enterprise identity is built on a set of open federation standards that enable Single Sign-On (SSO), delegated authorization, and automated user provisioning across hundreds of applications and services. Understanding these standards at a working technical level is essential for identity security professionals — both to implement them correctly and to identify when they are misconfigured.

SAML 2.0 (Security Assertion Markup Language): the dominant enterprise SSO standard for web applications, particularly for older and enterprise SaaS applications. SAML uses XML-based assertions to communicate authentication and attribute information between an Identity Provider (IdP — the system that authenticates the user: Okta, Azure Entra ID, Ping Identity) and a Service Provider (SP — the application the user is trying to access: Salesforce, Workday, ServiceNow). SAML SP-initiated flow: user navigates to SP, SP redirects to IdP with SAML AuthnRequest, user authenticates at IdP, IdP issues a SAML Response (XML assertion signed with IdP''s private key), response posted back to SP''s Assertion Consumer Service URL, SP validates the signature and grants access. SAML security consideration: the SAML Response must be cryptographically signed and the SP must validate the signature before trusting any assertion in the response. XML signature wrapping attacks exploit SPs that validate signatures but do not validate that the signed assertion is the one being evaluated.

OAuth 2.0: the authorization framework for delegated API access. OAuth 2.0 is not an authentication protocol — it enables an application to access resources on behalf of a user without receiving the user''s credentials. The four grant types (flows): Authorization Code (most secure — server-side web applications; the authorization code is exchanged for tokens server-side, never exposed to the browser), Authorization Code + PKCE (for public clients — mobile apps and SPAs that cannot keep a client secret; PKCE prevents authorization code interception attacks), Client Credentials (machine-to-machine — no user involved; the application authenticates directly to get an access token for its own resources), Device Flow (for input-constrained devices — smart TVs, CLI tools). Access tokens are typically short-lived (15 minutes to 1 hour). Refresh tokens are longer-lived and used to obtain new access tokens without re-authenticating.

OpenID Connect (OIDC): the authentication layer built on top of OAuth 2.0. OIDC adds the ID Token (a JWT containing claims about the authenticated user: sub, email, name, iat, exp, iss, aud) to the OAuth 2.0 Authorization Code flow. Applications use OIDC for user authentication: instead of implementing their own authentication, they delegate to an Identity Provider via OIDC and receive an ID Token confirming who the user is and an access token for API access. OIDC is the modern replacement for SAML in new application development.

SCIM (System for Cross-domain Identity Management): automates user provisioning and deprovisioning between identity providers and applications. When a new employee is created in Workday (HR system of record), SCIM propagates the user creation to Okta, which then provisions the user in all connected applications (Salesforce, GitHub, Slack, Google Workspace) within minutes. When an employee is terminated, SCIM propagates the deprovisioning, revoking access across all connected applications automatically. SCIM dramatically reduces the manual effort of access lifecycle management and eliminates the most common access control finding: terminated users retaining access.'
    ))
  WHERE chapter_id = v_ch AND order_index = 3;

  UPDATE public.videos SET
    description = 'MFA fatigue attacks bypass even strong MFA through social engineering. Master push bombing attacks, phishing-resistant MFA, Conditional Access risk signals, and adaptive authentication architecture.',
    translations = jsonb_build_object('en', jsonb_build_object(
      'title', 'MFA Fatigue Attacks, Conditional Access & Adaptive Authentication',
      'description', 'MFA fatigue attacks bypass even strong MFA through social engineering. Master push bombing, phishing-resistant MFA, Conditional Access risk signals, and adaptive authentication architecture.',
      'transcript', 'Multi-Factor Authentication dramatically reduces credential theft risk, but attackers have adapted. MFA fatigue attacks (also called push bombing or MFA bombing) exploit the human element of push-notification MFA: the attacker obtains a user''s credentials (through phishing or credential database purchase), then sends an MFA push notification request to the user''s phone. If the user declines, the attacker sends another. And another. At 2 AM, after 20 push notifications, some users approve the request just to make it stop. In September 2022, Uber was breached using exactly this technique: an attacker obtained a contractor''s VPN credentials, bombarded them with MFA push requests, and when the contractor finally approved, gained access to Uber''s internal systems.

MFA fatigue mitigations: Number Matching — the MFA push notification displays a number that the user must match to a number shown on their login screen. A user cannot approve without actually being present at the authentication prompt — eliminates passive approval of unsolicited pushes. Additional Context Display — the push notification shows the geographic location and device type of the login attempt. A user in London who receives a push notification showing "login from Tokyo using Windows 11" will recognize it as suspicious. These two controls together effectively eliminate MFA fatigue attacks for push-based MFA without requiring hardware key deployment.

Phishing-resistant MFA: FIDO2/WebAuthn is the gold standard. The user''s authentication device (hardware security key like YubiKey, or a passkey stored in a TPM) performs a cryptographic challenge-response where the response is bound to the specific origin (website URL) of the authentication request. A phishing site at bank-0f-america.com cannot trigger a FIDO2 authentication for bank.com — the origin binding prevents the credential from being used on a different domain. The US government''s CISA has issued guidance recommending organizations migrate all privileged and high-risk accounts to phishing-resistant MFA as their highest-priority identity security action.

Conditional Access is the policy engine that makes Zero Trust identity architecture operational. Conditional Access policies define: who (user or group identity), what (which application or resource), from where (location, named networks), with what device (compliant MDM-enrolled device vs. unmanaged), under what risk level (Azure AD Identity Protection risk score: low/medium/high) → then what happens (allow, require MFA, require compliant device, block access). Policy examples: "Require phishing-resistant MFA for all access to Azure portal and administrative roles" (protecting admin access), "Block access from Tor exit nodes and known VPN IP ranges" (reducing anonymous access risk), "Require compliant device for access to SharePoint containing confidential data" (data protection), "Require MFA when sign-in risk is medium or high" (risk-adaptive enforcement).

Adaptive authentication adjusts authentication requirements dynamically based on risk signals, rather than applying fixed rules. A user authenticating from their usual device, at their usual time, from their usual location, to their usual applications receives a seamless login experience. The same user authenticating from an unknown device, at 3 AM, from an unusual country, attempting to access the financial system they have never accessed before is prompted for step-up authentication — MFA re-verification, manager approval, or session termination depending on the risk level. Adaptive authentication delivers security without UX degradation: high-security for high-risk requests, frictionless experience for routine low-risk access.'
    ))
  WHERE chapter_id = v_ch AND order_index = 4;

  UPDATE public.videos SET
    description = 'IGA manages identity across the full employee lifecycle. Master joiner-mover-leaver processes, access certification, segregation of duties, role mining, and platforms like SailPoint and Saviynt.',
    translations = jsonb_build_object('en', jsonb_build_object(
      'title', 'Identity Governance & Administration (IGA) — Lifecycle, Certification & Segregation of Duties',
      'description', 'IGA manages identity across the full employee lifecycle. Master joiner-mover-leaver processes, access certification, segregation of duties, role mining, and platforms like SailPoint and Saviynt.',
      'transcript', 'Identity Governance and Administration (IGA) is the discipline that manages identities and their access rights across the full employee lifecycle, ensuring that the right people have the right access and that access is reviewed, certified, and revoked appropriately over time. While PAM addresses privileged accounts specifically, IGA addresses the complete population of identities in the organization.

The joiner-mover-leaver process is the foundational IGA workflow. Joiner (new employee or contractor): when a new person joins, their identity is created in the IdP (Okta, Azure Entra ID), and access is provisioned based on their role. Role-based access assignment: instead of manually selecting individual permissions, each role (Software Engineer, Finance Analyst, Customer Support Agent) maps to a set of approved applications and permissions. New employees get their role''s access automatically — minimizing provisioning time and ensuring consistency. Mover (role change): when an employee changes departments, is promoted, or takes on new responsibilities, their access must be updated. The critical action: remove access that is no longer appropriate for the new role, not just add new access. Access accumulation (also called privilege creep) — where employees retain all access from previous roles over years of job changes — is one of the most common audit findings and a significant insider threat risk factor. Leaver (departure): when an employee leaves, all access must be revoked — within the policy-defined SLA (typically 24 hours for voluntary departures, immediate for terminations). IGA platforms integrated with HR systems trigger automatic deprovisioning when a termination event is recorded, ensuring no manual step is required that could be missed.

Access certification (also called access review or recertification): a periodic process where managers and resource owners review and certify that their reports'' access is still appropriate. Frequency: quarterly for privileged access, annually for standard access. Process: the IGA platform generates a review campaign, sends each manager a list of their direct reports'' access, managers certify each access item (approve to retain, revoke to remove), and the IGA platform automatically enacts revocations. Evidence: completion reports showing which accesses were reviewed, who approved or revoked, and when — critical SOC 2 and ISO 27001 audit evidence. Common failure mode: rubber-stamp certification where managers approve all access without actually reviewing appropriateness. Mitigation: require managers to review specific high-risk accesses with additional scrutiny, implement random sampling audits of certified accesses, and use UEBA data to surface certifications where the user has never actually used the access being certified.

Segregation of Duties (SoD): the principle that no single individual should have the ability to execute a complete high-risk process without the involvement of another person. In financial systems: the person who can create a vendor in the payment system should not also be the person who can approve payments to that vendor (creates a fraud risk — a single insider could create a fictitious vendor and approve fraudulent payments to themselves). In IT systems: the person who can write code should not also be the person who approves that code''s deployment to production. SoD violations are a primary target of external financial auditors (SOX) and a significant finding in ISO 27001 and SOC 2 audits. IGA platforms implement SoD rule enforcement: an access request that would create a SoD violation is automatically blocked and escalated for risk acceptance review.

Role mining: the analytical process of examining current access patterns across the user population to design optimal RBAC roles. Instead of creating roles based on job descriptions (which may not reflect actual access needs), role mining analyzes what access each user actually has and clusters users with similar access patterns into candidate roles. This produces roles that reflect actual least-privilege needs rather than theoretical organizational charts. IGA platforms (SailPoint IdentityNow, Saviynt Enterprise Identity Cloud, IBM Security Verify Governance) provide role mining analytics that identify outliers (users with unusual access compared to peers) and role optimization opportunities (consolidating fragmented permissions into clean role definitions).'
    ))
  WHERE chapter_id = v_ch AND order_index = 5;

-- ─── MODULE 14: Threat Intelligence & Advanced Threat Hunting ─────────────────

  SELECT id INTO v_ch FROM public.chapters
    WHERE course_id = v_cid ORDER BY order_index LIMIT 1 OFFSET 13;
  IF v_ch IS NULL THEN RAISE EXCEPTION 'M14 chapter not found'; END IF;

  UPDATE public.videos SET
    description = 'The CTI lifecycle transforms raw threat data into finished intelligence that drives security decisions. Master collection sources, processing methods, analysis techniques, and intelligence product design.',
    translations = jsonb_build_object('en', jsonb_build_object(
      'title', 'Cyber Threat Intelligence (CTI) Lifecycle — Collection, Analysis & Dissemination',
      'description', 'The CTI lifecycle transforms raw threat data into finished intelligence that drives security decisions. Master collection sources, processing methods, analysis techniques, and intelligence product design.',
      'transcript', 'Cyber Threat Intelligence is the discipline of transforming raw information about threats into finished, actionable knowledge that enables better security decisions. The distinction between data and intelligence matters: a list of malicious IP addresses is data. A structured analysis of the threat actor who uses those IPs, their targeting criteria, their preferred initial access methods, their post-exploitation tradecraft, and the specific assets in your environment they are most likely to target — that is intelligence.

Intelligence has three levels. Strategic intelligence addresses the big picture: what threat actors are active in your sector, what their long-term objectives are, and what the broader geopolitical and criminal landscape means for your organization''s risk posture. Strategic intelligence is consumed by CISOs, board members, and senior leadership. It answers: what should we be investing in over the next 12 months? Operational intelligence focuses on specific campaigns and operations: a ransomware group is currently running a phishing campaign targeting healthcare organizations using PDF attachments impersonating Medicare notices. Operational intelligence is consumed by security managers and SOC leads. It answers: what threat do we need to prepare for this week? Tactical intelligence is highly specific: the IOCs (IP addresses, domain names, file hashes, email subjects) associated with the current campaign, the specific YARA rules that detect the malware being used, the specific Sigma rules that detect the TTPs being employed. Tactical intelligence is consumed by SOC analysts and detection engineers. It answers: what specific indicators should we add to our SIEM and endpoint protection today?

CTI lifecycle: Direction — define intelligence requirements: what threat actors are relevant to our industry and geography? what would be the most impactful attacks on our specific environment? Collection — gather raw data from diverse sources: open-source intelligence (news sites, security vendor blogs, academic research, government advisories), technical feeds (threat intelligence platforms, commercial feeds from Recorded Future and Mandiant), community sharing (ISACs, trusted peer groups), internal sources (incident response findings, SIEM telemetry, phishing report submissions), dark web monitoring (forums, marketplaces, paste sites where threat actors discuss campaigns and sell access). Processing — normalize and enrich raw data: convert IP addresses to ASN/geolocation/hosting provider, resolve domains to registration history and passive DNS, hash observed files against VirusTotal, and link individual IOCs to threat actor campaigns. Analysis — identify patterns, attribute activity to specific threat actors, assess the relevance and credibility of each intelligence item, and produce finished analysis products. Dissemination — deliver intelligence products to the right audience in the right format: machine-readable IOC feeds for SIEM ingestion, written briefs for SOC analysts, executive summaries for leadership.

CTI platforms: Recorded Future (premium commercial, AI-powered analysis, excellent for financial services and government), Mandiant Advantage (backed by Google, strong APT attribution), MISP (open-source, community-driven, widely used for ISAC intelligence sharing), OpenCTI (open-source, structured threat intelligence graph with STIX 2.1 data model), ThreatConnect (enterprise GRC integration), and Anomali (strong for security operations integration). ISACs: FS-ISAC (financial sector), H-ISAC (healthcare), E-ISAC (energy), MS-ISAC (state and local government), and sector-specific communities that share intelligence among peer organizations under controlled disclosure agreements.'
    ))
  WHERE chapter_id = v_ch AND order_index = 1;

  UPDATE public.videos SET
    description = 'MITRE ATT&CK is the universal language of adversary behavior. Master all 14 tactics, key techniques and sub-techniques, ATT&CK Navigator heat mapping, and using the framework for detection engineering.',
    translations = jsonb_build_object('en', jsonb_build_object(
      'title', 'MITRE ATT&CK Framework — All 14 Tactics, Techniques & Sub-Techniques Deep Dive',
      'description', 'MITRE ATT&CK is the universal language of adversary behavior. Master all 14 tactics, key techniques and sub-techniques, ATT&CK Navigator, and using the framework for detection engineering.',
      'transcript', 'MITRE ATT&CK (Adversarial Tactics, Techniques, and Common Knowledge) is the most important reference framework in modern threat detection and security operations. Created by MITRE Corporation and continuously updated based on real-world adversary observations, ATT&CK provides a structured, comprehensive taxonomy of attacker behaviors organized by the phase of the attack lifecycle in which they occur. Every SOC analyst, threat hunter, and detection engineer should know ATT&CK fluently.

ATT&CK Enterprise Matrix covers 14 tactics — the high-level adversary objectives at each stage of an intrusion: Reconnaissance (gathering information about the target before the attack), Resource Development (establishing infrastructure and acquiring tools for the attack), Initial Access (gaining the first foothold in the target environment), Execution (running malicious code), Persistence (maintaining access across reboots, credential rotations, and other disruptions), Privilege Escalation (gaining higher-level permissions), Defense Evasion (avoiding detection), Credential Access (stealing account names and passwords), Discovery (learning about the environment after gaining initial access), Lateral Movement (pivoting to additional systems), Collection (gathering data of interest to the attacker''s objective), Command and Control (communicating with compromised systems), Exfiltration (stealing data), and Impact (disrupting availability, integrity, or confidentiality to achieve the final objective).

Key techniques within each tactic: Initial Access — T1566 (Phishing, the most common initial access technique), T1190 (Exploit Public-Facing Application), T1133 (External Remote Services — VPN and RDP exploitation). Execution — T1059 (Command and Scripting Interpreter — PowerShell, Bash, Python used for malicious execution), T1203 (Exploitation for Client Execution). Persistence — T1053 (Scheduled Task/Job), T1547 (Boot or Logon Autostart Execution — Registry Run Keys, startup folders), T1543 (Create or Modify System Process). Privilege Escalation — T1068 (Exploitation for Privilege Escalation), T1134 (Access Token Manipulation). Defense Evasion — T1070 (Indicator Removal — log clearing, timestomping), T1036 (Masquerading — renaming malicious files to look legitimate), T1027 (Obfuscated Files or Information). Credential Access — T1003 (OS Credential Dumping — LSASS, SAM, NTDS.dit), T1110 (Brute Force), T1558 (Steal or Forge Kerberos Tickets — Kerberoasting, Golden Ticket). Lateral Movement — T1021 (Remote Services — RDP, SMB, WinRM), T1550 (Use Alternate Authentication Material — Pass-the-Hash, Pass-the-Ticket).

ATT&CK Navigator is the visualization tool for ATT&CK: it renders the full matrix as a heat map where you can color-code techniques by coverage (which techniques do we have detections for?), by threat actor relevance (which techniques does APT29 use?), or by detection priority. ATT&CK Navigator heat maps are the single most useful artifact for a detection engineering program: comparing your current detection coverage against the techniques used by threat actors relevant to your industry reveals your specific detection gaps.

Detection engineering with ATT&CK: for each technique you prioritize, develop one or more detection rules. T1003.001 (LSASS Memory) detection examples: Windows Event 10 (Sysmon process access to LSASS.exe), detection of known LSASS dump tool names (ProcDump, Task Manager dump, comsvcs.dll), and behavioral detection of unusual processes reading LSASS memory. Map every detection rule in your SIEM to its ATT&CK technique ID. This mapping enables two critical capabilities: coverage measurement (what percentage of high-priority techniques have at least one detection?), and gap analysis (which techniques used by our priority adversaries have no detection?).'
    ))
  WHERE chapter_id = v_ch AND order_index = 2;

  UPDATE public.videos SET
    description = 'Nation-state APT groups are the most sophisticated adversaries organizations face. Master the TTPs, targeting patterns, and malware families of Russian, Chinese, Iranian, and North Korean threat actors.',
    translations = jsonb_build_object('en', jsonb_build_object(
      'title', 'Nation-State APT Tracking & Adversary Profiling (Russia, China, Iran, North Korea)',
      'description', 'Nation-state APT groups are the most sophisticated adversaries. Master the TTPs, targeting patterns, and malware families of Russian, Chinese, Iranian, and North Korean threat actors.',
      'transcript', 'Advanced Persistent Threats (APTs) are sophisticated, often state-sponsored threat actors that conduct long-term, targeted intrusion campaigns. Unlike financially motivated criminal groups who execute attacks quickly and move on, APTs establish persistent access to target environments — sometimes maintaining undetected presence for months or years — in service of strategic intelligence collection, intellectual property theft, pre-positioning for potential future disruption, or financial objectives.

Russia — Primary APT groups: APT28 (Fancy Bear / Unit 26165, GRU military intelligence): focuses on government, defense, political organizations, and critical infrastructure. Known for spear-phishing campaigns with advanced implants, credential theft, and election interference operations. Responsible for the 2016 DNC breach and multiple NATO member government compromises. APT29 (Cozy Bear / Midnight Blizzard, SVR foreign intelligence): the most sophisticated Russian APT. Long-dwell-time espionage with extensive operational security. Responsible for the SolarWinds supply chain compromise (2020) and the Microsoft executive email breach (2024). TTPs: living-off-the-land (using legitimate Microsoft tools rather than custom malware), OAuth token theft, residential proxy infrastructure. Sandworm (Unit 74455, GRU): focuses on destructive operations targeting critical infrastructure. Responsible for the 2015 and 2016 Ukraine power grid attacks, NotPetya (2017, the most destructive cyberattack in history — $10B+ in global damages).

China — Primary APT groups: APT41 (Winnti, dual espionage and financial motivation): unique among state-sponsored APTs for conducting both government-directed espionage and financially motivated cybercrime. Targets technology companies for IP theft, gaming companies for financial fraud, and government targets for espionage. APT10 (Bronze Riverside / MenuPass): focuses on managed service providers as a path to reach multiple downstream targets simultaneously. The Operation Cloud Hopper campaign compromised MSPs in 12 countries to reach their clients. Volt Typhoon (Bronze Silhouette): pre-positioning in US critical infrastructure (power, water, transportation, communications) with the stated strategic goal of disrupting US response capability in the event of a Taiwan conflict. TTPs: almost exclusively living-off-the-land — Volt Typhoon is designed to be indistinguishable from normal network activity by avoiding custom malware entirely.

Iran — Primary APT groups: APT33 (Elfin / Refined Kitten): focuses on aerospace, energy, and petrochemical sectors. Known for destructive wiper malware (Shamoon wiped Saudi Aramco''s computers in 2012). APT34 (OilRig / Helix Kitten): focuses on Middle East targets in financial, government, and energy sectors. Sophisticated phishing campaigns and custom implants. APT35 (Charming Kitten / Phosphorus): focuses on academia, journalists, diplomats, and human rights activists. Known for elaborate social engineering via fake conference invitations and journalist personas.

North Korea — Primary APT groups: Lazarus Group (Bureau 121): the most financially motivated nation-state actor. Responsible for the 2016 Bangladesh Bank heist ($81M stolen via SWIFT), multiple cryptocurrency exchange heists (estimated $1.7B stolen in 2022 alone), and Sony Pictures attack (2014). APT38 (Bluenoroff, a Lazarus sub-group): exclusively focuses on financial theft through SWIFT targeting. Reconnaissance lasts 1–2 years before the actual theft is executed.

Detection and hunting approaches: APT detection requires behavioral detection, not just signature-based detection. Key behavioral indicators: long-dwell-time low-volume C2 traffic (beaconing at intervals that blend with normal traffic), certificate-based malware with valid code signing certificates, credential theft via memory forensics techniques, and large data staging before exfiltration. Threat hunting for APT activity focuses on the Discovery and Collection phases — where adversaries that successfully evaded initial detection are still operating before achieving their objective.'
    ))
  WHERE chapter_id = v_ch AND order_index = 3;

  UPDATE public.videos SET
    description = 'Threat hunting proactively finds adversaries before they achieve their objectives. Master hypothesis generation, hunt package design, SIEM and EDR query techniques, and documenting hunts that improve the detection program.',
    translations = jsonb_build_object('en', jsonb_build_object(
      'title', 'Hypothesis-Driven Threat Hunting — Methodology, Hunt Packages & TTP-Based Queries',
      'description', 'Threat hunting proactively finds adversaries before they achieve their objectives. Master hypothesis generation, hunt package design, SIEM and EDR query techniques, and hunt documentation.',
      'transcript', 'Threat hunting is the proactive, analyst-driven search for threats that have evaded automated detection. While SIEM rules and EDR behavioral analytics catch known patterns, sophisticated adversaries — particularly nation-state actors — design their operations to avoid triggering alerts. Threat hunting fills the gap by combining human analytical judgment with telemetry data to find the anomalies that rules cannot express.

The fundamental premise of threat hunting: if a sophisticated adversary is in your environment right now, what evidence would they have left, and where would you look for it? This adversary-first thinking is what distinguishes hunting from waiting for alerts. Hunters start with knowledge of adversary behavior (TTPs from ATT&CK, current threat intelligence) and search for evidence of that behavior in the data — rather than starting with an alert and investigating backward.

Hypothesis generation: every hunt starts with a testable hypothesis. Good hypotheses are specific (narrow enough to investigate), observable (the behavior leaves detectable traces in available data), and based on credible threat intelligence or known gaps in detection coverage. Hypothesis sources: ATT&CK coverage gaps (which techniques have no detection rule in our SIEM? those are hunt candidates), threat intelligence (current campaigns are using T1547.001 Registry Run Keys for persistence — have we seen any recently created Run Keys in our environment?), anomaly tips from SIEM/UEBA (a UEBA alert about unusual data access didn''t rise to incident threshold — hunt for additional supporting evidence), and environmental knowledge (we know our finance team never uses PowerShell — any PowerShell execution events from finance workstations should be investigated).

Hunt package design: document the hunt before executing it. A hunt package contains: hypothesis statement (clear, falsifiable), data sources required (which log types, which time window, which systems), query logic (the specific SIEM queries, EDR searches, or network analysis filters), expected false positive patterns (legitimate activity that might match the query and how to differentiate), success criteria (what constitutes a finding worth escalating to an incident?), and scope (which subset of the environment are you hunting in, and what is excluded?). Documenting hunts enables repeatability (the same hunt can be re-executed monthly without re-deriving the methodology), handoff (another analyst can execute the hunt from documentation alone), and conversion (a successful hunt that consistently finds malicious activity is a candidate for conversion to an automated detection rule).

SIEM hunt query examples (using Sentinel/KQL): Kerberoasting detection — identify TGS requests where the encryption type is RC4 (0x17), which is unusual for modern service accounts and is the encryption type requested by Kerberoasting tools: SecurityEvent | where EventID == 4769 | where TicketEncryptionType == "0x17" | where ServiceName != "krbtgt" | summarize count() by TargetUserName, ServiceName, bin(TimeGenerated, 1h). Living-off-the-land detection — PowerShell downloading from the internet: DeviceProcessEvents | where ProcessCommandLine contains "DownloadString" or ProcessCommandLine contains "WebClient" | where InitiatingProcessFileName == "powershell.exe" | project TimeGenerated, DeviceName, InitiatingProcessAccountName, ProcessCommandLine.

Hunt documentation and outcomes: after completing a hunt, document: whether the hypothesis was confirmed or refuted, any findings (true positive adversary activity) or notable anomalies discovered, recommendations for environment hardening based on hunt observations, and whether the hunt methodology should be converted to an automated detection rule. Successful hunts that result in incident findings should feed into the lessons-learned process. Unsuccessful hunts (hypothesis refuted) are also valuable — they confirm coverage and can be archived to avoid re-executing the same hunt unnecessarily.'
    ))
  WHERE chapter_id = v_ch AND order_index = 4;

  UPDATE public.videos SET
    description = 'Threat intelligence is only valuable when it reaches the tools and teams who need it. Master CTI-to-SIEM integration, SOAR playbook automation, STIX/TAXII standards, and building an MDR intelligence program.',
    translations = jsonb_build_object('en', jsonb_build_object(
      'title', 'Threat Intelligence Integration — SIEM Rules, SOAR Playbooks & MDR Feeds',
      'description', 'Threat intelligence is only valuable when it reaches the tools and teams who need it. Master CTI-to-SIEM integration, SOAR playbook automation, STIX/TAXII standards, and MDR intelligence feeds.',
      'transcript', 'Threat intelligence that exists in a platform but does not influence detection rules, response playbooks, or analyst priorities provides no security value. The integration of CTI into operational security tools — SIEM, SOAR, EDR, and MDR services — is the mechanism that converts intelligence investment into security outcomes.

SIEM integration: the most direct CTI integration pushes IOCs (IP addresses, domains, file hashes) into SIEM detection rules as threat intelligence feeds. Most SIEM platforms support threat intelligence table ingestion: a table populated with malicious indicators that other detection rules can reference. A network connection event is automatically enriched — if the destination IP appears in the threat intelligence table, the severity of the associated alert is elevated. SIEM platforms handle this differently: Microsoft Sentinel has a native Threat Intelligence blade and Threat Intelligence Matching Analytics rule template; Splunk Enterprise Security has the Threat Intelligence Framework (TI) that maintains threat lists and applies them across all alert types; Elastic SIEM supports threat intelligence ingestion via the Threat Intel integration.

IOC lifetime management is critical for SIEM integration. An IOC that is weeks or months old may have been abandoned by the threat actor and reassigned to a legitimate service — a blocklist rule based on stale IOCs generates false positives that erode analyst trust in the intelligence feed. Best practice: assign a confidence score and expiration date to every IOC. High-confidence IOCs with active usage evidence get 30-day expiration; lower-confidence IOCs get 7-day expiration. Automated expiration prevents stale IOC accumulation.

SOAR playbook automation: SOAR can automatically enrich alerts with threat intelligence context and execute response actions based on that context. Example playbook: a SIEM alert fires for a connection to a known C2 IP → the SOAR playbook automatically enriches the alert with context from Recorded Future (what threat actor uses this IP, what campaigns has it been observed in, what is the confidence score?), checks internal threat intelligence for any prior sightings of this IP in the organization''s environment, checks whether the connecting host is a critical asset, and if all three signals indicate high risk, automatically isolates the endpoint via the EDR API and creates a P1 incident ticket — all within seconds of the initial alert, before any analyst action.

STIX (Structured Threat Information eXpression) 2.1 is the JSON-based standard for representing threat intelligence objects: indicators, malware, threat actors, campaigns, attack patterns, courses of action, relationships. TAXII (Trusted Automated eXchange of Intelligence Information) 2.1 is the REST API standard for distributing STIX content: discovery (what collections are available?), get (retrieve all STIX objects in a collection), and push (contribute intelligence to a shared collection). STIX/TAXII enable machine-to-machine intelligence sharing: your CTI platform automatically ingests new IOCs from your ISAC''s TAXII server hourly, without manual download and import.

MDR (Managed Detection and Response) services include curated threat intelligence as part of their service. MDR providers (CrowdStrike Falcon Complete, Mandiant Managed Defense, Arctic Wolf, SentinelOne Vigilance) maintain their own threat intelligence teams who develop proprietary detections for emerging campaigns, push updated threat intelligence to all managed environments simultaneously, and proactively hunt in customer environments when new APT campaigns are identified. For organizations without dedicated CTI teams, MDR provides operational threat intelligence as a service.'
    ))
  WHERE chapter_id = v_ch AND order_index = 5;

-- ─── MODULE 15: Security Automation, SOAR & Compliance Tools ─────────────────

  SELECT id INTO v_ch FROM public.chapters
    WHERE course_id = v_cid ORDER BY order_index LIMIT 1 OFFSET 14;
