  SELECT id INTO v_ch FROM public.chapters
    WHERE course_id = v_cid ORDER BY order_index LIMIT 1 OFFSET 17;
  IF v_ch IS NULL THEN RAISE EXCEPTION 'M18 chapter not found'; END IF;

  UPDATE public.videos SET
    description = 'The capstone places you inside a real consulting engagement. Understand the TechNova Financial scenario, CEO mandate, enterprise stack, and what world-class security consultants assess in week one.',
    translations = jsonb_build_object('en', jsonb_build_object(
      'title', 'Capstone Brief — The CEO Mandate & Full Enterprise Stack Assessment',
      'description', 'The capstone puts you inside a real consulting engagement. Master the TechNova scenario, CEO mandate, enterprise stack assessment methodology, and week-one deliverables.',
      'transcript', 'Welcome to the Enterprise Capstone. Over the next five lessons, you will work through a complete, realistic security consulting engagement for TechNova Financial — a $200M Series D fintech company facing a $15M contract at risk if they cannot demonstrate security and compliance maturity within six months. This scenario mirrors real engagements at Big 4 advisory firms (Deloitte, PwC, EY, KPMG) and boutique security consultancies. Everything you produce in this capstone — every deliverable, every analysis, every recommendation — is portfolio-quality work you can present in interviews and consulting engagements.

TechNova Financial scenario: TechNova provides AI-powered treasury management software to mid-market and enterprise corporations. Their platform processes $2.4B in daily transaction volume for 340 corporate clients. TechNova has grown rapidly from a 50-person startup to a 420-person company through organic growth and two acquisitions. Their largest enterprise client, ContinentalBank Corp, has notified TechNova that renewal of their $15M annual contract (30% of TechNova''s ARR) requires SOC 2 Type II certification, ISO 27001 certification, GDPR compliance evidence, and a completed vendor risk program — all within six months. The CEO has issued a mandate to the CISO: "Whatever it takes. This contract cannot be lost."

Your assignment: you have been engaged as the lead security consultant. You are responsible for six workstreams: (1) Technical Security Gap Assessment, (2) GRC Program Build (risk register, policy library, control matrix, evidence package), (3) SOC 2 Type II Readiness, (4) ISO 27001 Readiness, (5) AI Governance for TechNova''s customer-facing LLM treasury assistant, and (6) Vendor Risk Program. You have a six-person consulting team and 26 weeks. Budget: $480K for the engagement.

TechNova enterprise stack (what you''re securing): Infrastructure — AWS (primary, us-east-1 and eu-west-1 regions for GDPR data residency), Microsoft Azure (Microsoft 365, Entra ID, Azure AD for identity), GitHub (source code management for 12 active product repositories). Applications — TechNova platform (React frontend, Node.js/Python microservices, PostgreSQL RDS, Redis cache), Salesforce (CRM — contains client contact data and contract information), Workday (HR system — employee data, compensation, org chart), ServiceNow (IT ticketing and change management), Slack (primary internal communication), Zoom (video conferencing). Identity — Okta (primary IdP, SSO for all SaaS applications), Microsoft Entra ID (M365 authentication, Azure resource access). Monitoring — Datadog (application performance monitoring, infrastructure metrics — not yet configured for security monitoring). The two acquisitions brought legacy systems: TreasuryCo acquisition (18 months ago) brought an on-premises application server running Windows Server 2016 with direct database access credentials shared among 6 users; FinAnalytics acquisition (6 months ago) brought a Python ML model serving API deployed on bare-metal servers in a co-location facility with no EDR coverage.

Week one deliverables for a real consulting engagement: preliminary threat model (who is most likely to attack TechNova? what are their likely objectives and techniques?), initial risk register draft (top 15 enterprise risks based on available information, pending technical assessment completion), discovery questionnaire results review (pre-engagement questionnaire completed by TechNova''s IT team — review for completeness and identify follow-up questions), and the week-two fieldwork plan (schedule of technical assessments, stakeholder interviews, and evidence collection sessions). The speed and quality of week-one work determines the engagement''s trajectory — clients judge the competence of their consultants in the first week.'
    ))
  WHERE chapter_id = v_ch AND order_index = 1;

  UPDATE public.videos SET
    description = 'A technical security gap analysis reveals the true state of an organization''s defenses. Learn the assessment methodology, gap matrix design, risk rating methodology, and producing a prioritized remediation roadmap.',
    translations = jsonb_build_object('en', jsonb_build_object(
      'title', 'Technical Security Posture Review — Gap Analysis Across All Domains',
      'description', 'A technical security gap analysis reveals the true state of defenses. Learn the assessment methodology, gap matrix design, risk rating, and producing a prioritized remediation roadmap for TechNova.',
      'transcript', 'The technical security gap analysis is the diagnostic phase of the engagement: a systematic assessment of TechNova''s current security posture across every relevant domain, producing a gap matrix that identifies what exists, what is missing, and what the risk implications are of each gap. This is the most time-intensive deliverable of the engagement and the foundation on which all subsequent workstreams depend.

Assessment domains for TechNova: Identity and Access Management (is Zero Trust identity architecture implemented? is MFA enforced for all users? are privileged accounts managed via PAM? is the JML process automated?), Cloud Security (AWS and Azure CSPM findings, IAM policy least-privilege assessment, encryption configuration, logging completeness, container security for any containerized workloads), Application Security (is SAST/DAST deployed in CI/CD? are known OWASP vulnerabilities present in TechNova''s application? is the API authenticated and properly authorized?), Endpoint Security (is EDR deployed on all endpoints including the TreasuryCo legacy Windows server and FinAnalytics bare-metal servers? are endpoints managed via MDM?), Network Security (network segmentation assessment — is the legacy TreasuryCo application server on the same network segment as production? is the co-location facility connected to the AWS environment via a secure VPN with appropriate controls?), Logging and Detection (is a SIEM deployed? what log sources are connected? is there a SOC or MDR service monitoring for threats?), Vulnerability Management (is there a vulnerability scanning program? what are the current findings? what is the remediation SLA and compliance rate?), and Incident Response (is there a documented IR plan? has it been tested? who is on the IR team?).

Gap matrix structure: for each assessment domain, document the findings in a consistent format. Current State (what exists today — based on evidence reviewed, not assertions), Required State (what SOC 2, ISO 27001, and organizational risk tolerance requires), Gap (the specific delta between current and required state), Risk Rating (Critical/High/Medium/Low based on both the severity of the gap and the likelihood of exploitation), Remediation Effort (hours of work estimated to close the gap), Remediation Timeline (which 30/60/90/180-day bucket does this fall into?), and Remediation Owner (TechNova team member or TechNova with consulting support?).

TechNova-specific critical gaps (based on scenario information): EDR coverage gap on TreasuryCo legacy server and FinAnalytics bare-metal servers (Critical — these systems have no behavioral threat detection, and the FinAnalytics ML API is internet-accessible). Shared database credentials on TreasuryCo legacy system (Critical — six users sharing one database credential eliminates accountability and makes individual access review impossible). No SIEM or security monitoring (Critical — there is no capability to detect an active intrusion; TechNova has no MTTD). MFA not universally enforced (High — Okta is deployed but not configured to enforce MFA for all applications — spot-check found 3 SaaS applications accessible without MFA). No formal vulnerability management program (High — Datadog provides uptime monitoring but no security scanning; last vulnerability scan date unknown).

Remediation roadmap: organize gaps into three horizons. Horizon 1 — 30 days (Critical gaps requiring immediate action regardless of audit timeline): deploy EDR on all uncovered systems, remove shared credentials and implement individual accounts, engage an MDR service for immediate threat detection coverage. Horizon 2 — 60–90 days (High gaps that must be closed for SOC 2 and ISO 27001 audit scope): implement MFA enforcement for all applications, deploy vulnerability scanning and establish remediation SLAs, deploy SIEM with critical log sources. Horizon 3 — 90–180 days (Medium gaps and structural improvements): implement PAM for privileged accounts, deploy CSPM for continuous cloud security monitoring, implement formal change management process, complete network segmentation review and remediation.'
    ))
  WHERE chapter_id = v_ch AND order_index = 2;

  UPDATE public.videos SET
    description = 'The GRC program is the structural foundation of security compliance. Build TechNova''s risk register, policy library, and control evidence package from scratch using professional consulting methodology.',
    translations = jsonb_build_object('en', jsonb_build_object(
      'title', 'GRC Program Build — Risk Register, Policy Library & Control Evidence Package',
      'description', 'The GRC program is the foundation of compliance. Build TechNova''s risk register, policy library, and control evidence package using professional consulting methodology.',
      'transcript', 'Building a GRC program from scratch for a company that has never had one is one of the most common and most valuable services security consultants provide. TechNova has grown from startup to mid-market without a formal GRC function — they have informal practices, some documented policies, and significant gaps. Your job is to build the foundational GRC program that both satisfies SOC 2 and ISO 27001 requirements and genuinely reduces organizational risk.

Risk register construction for TechNova: start with the threat landscape relevant to fintech companies. Primary threats: ransomware targeting financial data (Critical inherent risk — TechNova processes $2.4B in daily transactions and would be a high-value ransomware target), supply chain attack via software dependency (High — TechNova''s Node.js and Python applications have hundreds of open-source dependencies; a Log4Shell-type event in any of them creates immediate exposure), insider threat from recent acquisitions (High — two acquisitions in 18 months bring employees from different security cultures with varying access controls), regulatory action for GDPR non-compliance (High — TechNova has EU customers and processes EU personal data without a documented GDPR compliance program), third-party breach via payment processor (Medium — TechNova integrates with banking APIs that have their own security postures).

For each risk, complete all risk register fields: inherent likelihood and impact scores, current controls (what exists today), control effectiveness rating, residual likelihood and impact, treatment decision, and treatment plan. For the ransomware risk: Inherent Likelihood 4 (Likely, based on current targeting of fintech companies), Inherent Impact 5 (Catastrophic, based on $2.4B daily transaction volume and client contract exposure), Inherent Risk Score 20 (Critical). Current controls: endpoint protection on most (not all) systems, backup in place but untested for ransomware recovery, no EDR coverage on legacy systems. Control Effectiveness: Poor (EDR gaps, untested backup, no IR plan). Residual Risk Score 16 (High — still elevated due to control gaps). Treatment: Mitigate. Treatment Plan: deploy EDR on all systems (30 days), implement and test immutable backups with 24-hour RTO (60 days), develop and exercise ransomware IR playbook (90 days). Target Residual Risk Score 8 (Medium — acceptable after treatment completion).

Policy library build: TechNova needs 10 core policies to satisfy SOC 2 and ISO 27001 requirements. Using the policy templates provided in the consulting engagement toolkit, customize each policy for TechNova''s environment and risk profile. Policy 1 — Information Security Policy: top-level policy establishing the ISMS, CISO role, security objectives, and governance structure. This policy is approved by the CEO and referenced in the SOC 2 System Description and ISO 27001 Clause 5 evidence. Policy 2 — Access Control Policy: user provisioning, access review schedule (quarterly), MFA requirement, privileged access requirements, termination procedures. Policy 3 — Incident Response Policy: IR team structure, incident classification criteria, escalation thresholds, notification obligations, post-incident review requirement. Policy 4 — Data Classification and Handling Policy: classification levels (Public/Internal/Confidential/Restricted), classification of TechNova data types (transaction data = Restricted, employee data = Confidential, marketing materials = Public), handling requirements for each level. Policy 5 — Vendor Risk Management Policy: vendor tiering criteria, assessment requirements by tier, BAA/DPA requirements, monitoring cadence.

Control evidence package: for each of the 30 controls in your control matrix (mapped to SOC 2 TSC and ISO 27001 Annex A), document the evidence that demonstrates the control is implemented and operating. Organize evidence in a shared drive with a folder structure that mirrors your control matrix: /Evidence/SOC2/CC6-Logical-Access/CC6.1-MFA/[evidence files]. For each evidence folder, include a cover sheet identifying the control, the TSC reference, the evidence period covered, and the auditor request reference. Evidence completeness by audit day one is the single most important audit preparation milestone — it demonstrates control confidence and dramatically reduces audit fieldwork friction.'
    ))
  WHERE chapter_id = v_ch AND order_index = 3;

  UPDATE public.videos SET
    description = 'Three advanced workstreams round out the TechNova engagement. Build the AI governance threat model, implement the identity security roadmap, and complete vendor risk assessments for TechNova''s three critical vendors.',
    translations = jsonb_build_object('en', jsonb_build_object(
      'title', 'AI Governance, Identity Security & Vendor Risk Deliverables',
      'description', 'Three advanced workstreams round out the engagement. Build TechNova''s AI governance framework, identity security roadmap, and vendor risk program for three critical vendors.',
      'transcript', 'Three of the six capstone workstreams address the most advanced security disciplines in the program: AI governance for TechNova''s LLM treasury assistant, identity security architecture, and vendor risk management. These deliverables demonstrate the capabilities that distinguish Aladiah graduates from candidates with narrow technical or compliance backgrounds.

AI Governance for TechNova''s Treasury Assistant: TechNova recently deployed an AI-powered treasury assistant that allows corporate clients to query their treasury positions, generate cash flow forecasts, and receive market commentary using a GPT-4-class LLM with RAG access to client-specific treasury data. This system presents significant AI security and governance risks that require immediate assessment.

AI governance deliverable — five components: (1) OWASP LLM Top 10 threat model: assess the treasury assistant against each of the 10 LLM risks. Critical findings: LLM01 (Prompt Injection) — the system has no input validation; a client user could potentially craft a prompt that causes the assistant to access or summarize another client''s treasury data from the shared RAG knowledge base. LLM06 (Excessive Agency) — the assistant has write access to generate transaction recommendations that are displayed to users without any flag that they are AI-generated; in some configurations, users have reported acting on AI recommendations as if they were authoritative. (2) NIST AI RMF assessment: complete the Map and Measure functions for the treasury assistant — categorize the risk level (High Risk due to financial advice context and access to sensitive client data), identify applicable regulations (EU AI Act Limited Risk tier at minimum due to automated financial recommendations, potentially High Risk under some interpretations), and document required human oversight mechanisms. (3) AI governance policy: TechNova''s AI Governance Policy covers permitted use cases for the treasury assistant, required disclosures to end users (all AI-generated content must be labeled), prohibited uses (the assistant must not make trade execution recommendations), human oversight requirements (treasury assistant outputs over $1M threshold must be reviewed by a human before client presentation), and model monitoring cadence (weekly accuracy and bias review). (4) EU AI Act risk classification: assess whether the treasury assistant falls under Limited Risk (transparency obligations) or High Risk (full compliance obligations). Legal analysis: automated financial advice systems may fall under High Risk Category (essential private services — creditworthiness and financial assessment). Recommend engaging EU AI Act legal counsel to confirm classification. (5) Monitoring program: implement logging of all treasury assistant queries and responses, weekly review of output quality and accuracy, quarterly bias assessment across client segments.

Identity Security deliverable — PAM implementation plan for 12 privileged accounts: identify the 12 highest-risk privileged accounts (2 AWS root accounts, 4 AWS admin IAM roles, 3 database administrator accounts, 3 Okta super administrators), design CyberArk PAM deployment for these accounts (password vaulting, JIT access with manager approval, session recording), define access review cadence (quarterly, with manager certification), and develop the transition plan (migration from current shared credentials to vaulted individual accounts with defined business justification per access).

Vendor Risk deliverable — three critical vendor assessments: TechNova''s critical vendors are Stripe (payment processing — access to financial transaction data), AWS (cloud infrastructure — hosts all production systems and customer data), and OpenAI (API provider for the treasury assistant LLM). Complete SIG assessments for each, produce risk scorecards with tier classifications, document contract security clause gaps (does the Stripe contract contain a DPA? does it have a breach notification SLA? is there a right-to-audit clause?), and produce contract security clause recommendations for the next renewal cycle.'
    ))
  WHERE chapter_id = v_ch AND order_index = 4;

  UPDATE public.videos SET
    description = 'The board presentation is the culminating deliverable of the capstone. Learn to deliver a 15-minute security briefing to a simulated board panel, assemble your professional portfolio, and earn the AI Security Pro certification.',
    translations = jsonb_build_object('en', jsonb_build_object(
      'title', 'Board Presentation & AI Security Pro Certification Portfolio',
      'description', 'The board presentation is the culminating deliverable. Learn to deliver a 15-minute board security briefing, assemble your professional portfolio, and earn the AI Security Pro certification.',
      'transcript', 'The capstone culminates in two deliverables that demonstrate your readiness for senior cybersecurity roles: a 15-minute board presentation to a simulated panel of TechNova executives and board members, and a complete professional portfolio assembling all six workstream deliverables into a consulting-quality package.

Board presentation preparation: your audience is TechNova''s four-person panel representing the CEO (business outcomes focus), CISO (technical validation), external auditor (compliance rigor), and a board member from the Audit and Risk Committee (governance oversight). Each panelist has different priorities and will ask different questions. Prepare for each perspective: the CEO wants to know if the $15M contract will be saved and what it will cost. The CISO wants to know if the technical gaps identified are accurately assessed and whether the remediation roadmap is realistic. The auditor wants to know if the control evidence package is audit-grade and whether the readiness timeline is credible. The board member wants to know if the board has appropriate oversight information and whether TechNova''s residual risk after remediation is acceptable.

Presentation structure (15 minutes + 5 minutes Q&A): Opening (1 minute): "TechNova is in a strong position to achieve the required certifications and save the ContinentalBank contract within the six-month timeline. Here is what we found and what we recommend." Slide 1 — Security Posture Today (2 minutes): current state in 5 key metrics — EDR coverage, MFA enforcement, vulnerability scanning, logging completeness, policy documentation status. Use red/yellow/green to make the picture immediately clear. Slide 2 — Top 5 Risks in Financial Terms (3 minutes): present the five highest-priority items from the risk register with estimated financial exposure. Frame each as: risk name, probability, financial impact range, current control effectiveness, treatment investment required. Slide 3 — Compliance Readiness Timeline (3 minutes): 26-week milestone chart showing SOC 2 audit-ready date (week 16), ISO 27001 Stage 1 audit date (week 18), Stage 2 audit date (week 24), and client certification delivery date (week 26). Which milestones are on track and which are at risk? Slide 4 — Investment Required (3 minutes): total investment required ($480K consulting, $220K technology tooling, $85K audit fees = $785K total) versus the $15M contract at risk — a 20x ROI case for the investment. Slide 5 — Decision Request (3 minutes): two decisions needed from the board: approve the $785K total investment, and approve the AI governance policy (which requires board-level ratification under the EU AI Act compliance framework).

Portfolio assembly: the professional portfolio contains six sections corresponding to the six workstreams. Each section opens with an executive summary (1 page, business language) followed by the technical deliverables. Section 1: Technical Security Gap Analysis (gap matrix, risk ratings, remediation roadmap). Section 2: GRC Program (risk register, policy library, control matrix). Section 3: SOC 2 Readiness Package (control-to-evidence mapping, PBC list pre-population, readiness assessment findings). Section 4: ISO 27001 Readiness Package (SoA draft, ISMS scope document, clause gap analysis). Section 5: AI Governance Framework (OWASP LLM threat model, NIST AI RMF assessment, AI governance policy, EU AI Act classification analysis). Section 6: Vendor Risk Program (three vendor SIG assessments, risk scorecards, contract security clause recommendations, ongoing monitoring plan).

AI Security Pro Certification: awarded upon successful capstone completion to students who demonstrate mastery across all four phases of the program. The certification portfolio serves as the primary evidence of capability for hiring managers and clients. Unlike traditional certifications that test multiple-choice recall, AI Security Pro demonstrates the ability to execute a real consulting engagement — from initial assessment through board presentation. This portfolio-based evidence of practical capability is what separates Aladiah graduates in the job market. Your capstone deliverables are professional artifacts you own, built from real methodology applied to a realistic scenario. They belong in your professional portfolio from your first interview onward.'
    ))
  WHERE chapter_id = v_ch AND order_index = 5;

END $$;

